import{_ as r,a0 as t,w as o,s as d,ao as l,I as n,x as s,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 Linux 上用 zram 替代傳統交換空間 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 zram 替代傳統交換空間 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 zram 替代傳統交換空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 zram 替代傳統交換空間 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221111.4 ⭐️⭐️ Drop swap for zram on Linux","title":"在 Linux 上用 zram 替代傳統交換空間","tag":"202301","desc":""},"relativePath":"202301/20221111.4 ⭐️⭐️ Drop swap for zram on Linux.md","filePath":"[post].md"}'),m={name:"202301/20221111.4 ⭐️⭐️ Drop swap for zram on Linux.md"};function c(h,a,g,z,u,k){const e=t("Link");return o(),d("div",null,[a[22]||(a[22]=l(`<h1 id="在-linux-上用-zram-替代傳統交換空間" tabindex="-1">在 Linux 上用 zram 替代傳統交換空間 <a class="header-anchor" href="#在-linux-上用-zram-替代傳統交換空間" aria-label="Permalink to “在 Linux 上用 zram 替代傳統交換空間”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/28/113826twvkkbrso9ws2kss.jpg" alt=""></p><blockquote><p>zram 是一個用於創建內存壓縮緩存的工具，特別是可以用作交換空間。</p></blockquote><p>我在我的電腦上花了很多時間（我是説工作），我發現了很多有趣的東西。其中最近引起我注意的是 <code>zram0</code> 設備。我是在幾個月前寫一篇文章時第一次注意到它，它顯示在 <code>lsblk</code> 命令的輸出中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM   SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>sda             8:0    0 931.5G  0 disk</span></span>
<span class="line"><span>├─sda1          8:1    0   600M  0 part</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>zram0         252:0    0     8G  0 disk [SWAP]</span></span></code></pre></div><p>它被識別為交換空間，這就是首先引起我的好奇心的原因，所以我做了一些研究。zram 最初被稱為 “<ruby>壓縮緩存<rt>compcache</rt></ruby>”，即 “壓縮的高速緩存”。事實證明，zram 是一個用於創建內存內壓縮緩存的工具，特別是作為交換空間使用。</p><p>但為什麼呢？</p><p>當我開始研究 zram 時，我只發現了幾篇關於將 zram 用於交換空間的基礎文章。起初，這對我來説似乎有點違反直覺。畢竟，如果你的內存快用完了，你把頁面交換到內存中的虛擬驅動器中，有什麼好處呢？</p>`,8)),n("p",null,[a[2]||(a[2]=s("然後我找到了 Fedora 項目的維基頁面，它提議使用 ",-1)),n("ruby",null,[p(e,{href:"https://fedoraproject.org/wiki/Changes/SwapOnZRAM"},{default:i(()=>[...a[0]||(a[0]=[s("zram 交換空間",-1)])]),_:1}),a[1]||(a[1]=n("rt",null,"swap-on-zram",-1))]),a[3]||(a[3]=s("。該建議説：“交換是有用的，除了它的速度很慢。zram 是一個使用了壓縮的內存驅動器。在啓動時創建一個 zram 交換空間，並且不再使用默認的交換分區。”",-1))]),a[23]||(a[23]=n("p",null,"該頁面的其餘部分是關於它的細節、好處、副作用和反饋。",-1)),a[24]||(a[24]=n("h3",{id:"linux-上用於交換空間的-zram",tabindex:"-1"},[s("Linux 上用於交換空間的 zram "),n("a",{class:"header-anchor",href:"#linux-上用於交換空間的-zram","aria-label":"Permalink to “Linux 上用於交換空間的 zram”"},"​")],-1)),a[25]||(a[25]=n("p",null,"使用 zram 作為交換空間，與常規的基於分區或基於文件的交換空間做的事情相同。當內存壓力過大時，一些最近使用最少的數據會被移到交換空間。平均來説，它會被壓縮到其原始大小的 50% 左右，並被放置在內存的 zram 空間中。這比將這些內存頁存儲在硬盤上要快得多，並可以釋放出它所使用的內存用於其他用途。",-1)),a[26]||(a[26]=n("h3",{id:"節省交換空間",tabindex:"-1"},[s("節省交換空間 "),n("a",{class:"header-anchor",href:"#節省交換空間","aria-label":"Permalink to “節省交換空間”"},"​")],-1)),n("p",null,[a[5]||(a[5]=s("我試圖找到關於配置多少交換空間或 zram 交換空間的總結建議。這使我重新回顧了交換空間的設置，以及我之前的文章《",-1)),p(e,{href:"https://opensource.com/article/19/2/swap-space-poll"},{default:i(()=>[...a[4]||(a[4]=[s("現代 Linux 系統的正確交換空間是多少？",-1)])]),_:1}),a[6]||(a[6]=s("》。就我所知，從 RHEL 和 Fedora 的最新文檔來看，推薦的交換空間數量並沒有改變。不過，該文檔忽略了 zram 的使用。",-1))]),a[27]||(a[27]=l(`<p>然而，在不使用 zram 的舊版 Linux 或 zram 被禁用的情況下，之前文章中的表格仍然為交換空間的分配提供了一個好的起點。</p><p>我找到的關於 zram 功能的文檔在 zram 如何根據內存大小分配空間，以及分配給 zram 交換空間的數量方面是不一致的。</p><p>由於缺乏權威性的文檔，我進行了一些實驗來憑經驗確定用於分配 zram 交換空間的算法。我為此使用了我自己的物理和虛擬系統。結果很有趣，與我迄今為止發現的任何文檔都不一致。</p><p>在所有足夠大的系統上，zram 的默認大小是 8GB，但在內存較小的主機上通常會大大減少。在我用於測試的一台虛擬機（VM）上，可以訪問 4GB 的內存，zram 的虛擬交換空間被分配為 3.8GB。我的一台舊戴爾電腦擁有 8GB 的內存，zram 被設置為 7.6GB。當內存減少到 2GB 時，zram 就減少到 1.9GB。</p><p>我擁有的所有內存超過 8GB 的物理和虛擬主機都顯示正好是 8GB 的 zram。這包括我擁有 64GB 內存的主工作站和其他擁有 16GB 或 32GB 內存的主機。</p><p>基於這幾個數據點，我可以得出這樣的結論：目前的默認設置是最多 8GB 的 zram，而在 8GB 或以下的主機上，zram 佔內存的 95%。</p><p>我讀過一些文章，其中提到了 zram 交換空間的其他大小，甚至高達 100% 的內存，但這些似乎都是理論上的，而不是現實。</p><p>你的發行版可能不同，但這裏是 Fedora 和類似發行版的實際 zram 交換空間的分配情況：</p><ul><li>內存 ⇐ 8 GB：0.95 × 內存</li><li>內存 &gt; 8 GB:8 GB</li></ul><p>請注意，zram 交換空間大小的算法並沒有基於對任何給定的現實世界的系統或應用程序的 “最佳” 交換大小的建議。這種 zram 交換空間的分配是一種相當概率性的方法，它應該在廣泛的 Linux 主機上運行良好。然而，最大的 zram 交換空間大小被配置為 8GB，而且我一直推薦 8GB 作為傳統交換空間的最大容量，我想我可以説它反映了 zram 交換空間的最佳大小。</p><h3 id="管理-zram-交換空間" tabindex="-1">管理 zram 交換空間 <a class="header-anchor" href="#管理-zram-交換空間" aria-label="Permalink to “管理 zram 交換空間”">​</a></h3><p>zram 的默認值保存在 <code>/usr/lib/systemd/zram-generator.conf</code> 配置文件中。以下是我的一個測試虛擬機，分配了 5097GB 的內存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /usr/lib/systemd/zram-generator.conf</span></span>
<span class="line"><span># This config file enables a /dev/zram0 device with the default settings:</span></span>
<span class="line"><span># - size - same as available RAM or 8GB, whichever is less</span></span>
<span class="line"><span># - compression - most likely lzo-rle</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># To disable, uninstall zram-generator-defaults or create empty</span></span>
<span class="line"><span># /etc/systemd/zram-generator.conf file.</span></span>
<span class="line"><span>[zram0]zram-size= min(ram, 8192)</span></span></code></pre></div><p>你可以在 <code>zram-generator.conf</code> 配置文件的最後一行改變默認的 zram 交換空間大小。但我建議不要這樣做，除非你能明確説明這樣做的原因，並在你做任何改變後測試你的結果。像 Linux 中的許多其他配置默認值一樣，zram 的默認值已經被很好地測試過了，適合大多數使用情況。</p><h3 id="監控-zram" tabindex="-1">監控 zram <a class="header-anchor" href="#監控-zram" aria-label="Permalink to “監控 zram”">​</a></h3><p>可以使用 <code>zramctl</code> 工具來查看 zram 的當前狀態。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># zramctl</span></span>
<span class="line"><span>NAME       ALGORITHM DISKSIZE DATA COMPR TOTAL STREAMS MOUNTPOINT</span></span>
<span class="line"><span>/dev/zram0 lzo-rle       4.8G   4K   80B   12K       4[SWAP]</span></span></code></pre></div><p>傳統的 <code>swapon</code> 命令也可以用來查看交換，包括作為交換使用的 zram：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># swapon --show</span></span>
<span class="line"><span>NAME       TYPE      SIZE USED PRIO</span></span>
<span class="line"><span>/dev/zram0 partition 4.8G   0B  100</span></span></code></pre></div><p>需要注意的是，<code>zramctl</code> 在不包含數據時不報告 zram，所以結果會包含空輸出。而像 <code>lsblk</code>、<code>swapon</code>、 <code>top</code>、<code>free</code>、<code>htop</code> 等工具，即使不包含數據，也會顯示 zram。</p><h3 id="停用-zram" tabindex="-1">停用 zram <a class="header-anchor" href="#停用-zram" aria-label="Permalink to “停用 zram”">​</a></h3><p><code>swapoff -a</code> 命令會關閉 zram 交換空間以及用作交換的傳統 HDD 或 SSD 存儲。<code>swapon -a</code> 命令在 zram 為空時不顯示它，可以使用 <code>zramctl /dev/zram0</code> 代替。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># swapon --show# lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM  SIZE RO TYPE MOUNTPOINTS</span></span>
<span class="line"><span>sda             8:00  120G  0 disk</span></span>
<span class="line"><span>├─sda1          8:10    1G  0 part /boot/efi</span></span>
<span class="line"><span>├─sda2          8:20    1G  0 part /boot</span></span>
<span class="line"><span>└─sda3          8:30  118G  0 part</span></span>
<span class="line"><span>  ├─vg01-root 253:00   10G  0 lvm  /</span></span>
<span class="line"><span>  ├─vg01-swap 253:10    3G  0 lvm  [SWAP]</span></span>
<span class="line"><span>  ├─vg01-usr  253:10   30G  0 lvm  /usr</span></span>
<span class="line"><span>  ├─vg01-home 253:20   10G  0 lvm  /home</span></span>
<span class="line"><span>  ├─vg01-var  253:30   30G  0 lvm  /var</span></span>
<span class="line"><span>  └─vg01-tmp  253:40   10G  0 lvm  /tmp</span></span>
<span class="line"><span>sr0            11:01 1024M  0 rom</span></span>
<span class="line"><span>zram0         252:00    0B  0 disk</span></span>
<span class="line"><span># zramctl## zramctl /dev/zram0</span></span>
<span class="line"><span>NAME       ALGORITHM DISKSIZE DATA COMPR TOTAL STREAMS MOUNTPOINT</span></span>
<span class="line"><span>/dev/zram0 lzo-rle         0B   0B    0B    0B       4</span></span></code></pre></div><p>注意，<code>/dev/zram0</code> 在這些命令中並沒有顯示為交換空間，直到它被用於該目的。這給我造成了一些困惑，直到我的實驗表明這是事實。</p><h3 id="創建-zram-交換空間" tabindex="-1">創建 zram 交換空間 <a class="header-anchor" href="#創建-zram-交換空間" aria-label="Permalink to “創建 zram 交換空間”">​</a></h3><p>zram 本身已經存在了大約 20 年，但只是在過去的一兩年裏才在一些發行版上作為交換空間使用。你的一些或所有主機上當前的 Linux 環境可能沒有用 zram 創建交換空間。如果是這種情況，它可以很容易地被補救。</p><p>對於 Fedora 32，它是默認使用 zram 交換空間之前的最後一個版本，它只需要三個簡單的命令。</p><p>首先，驗證是否存在 <code>zram-swap.service</code> 文件，它作為 <code>zram</code> RPM 包的一部分安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl status zram-swap</span></span>
<span class="line"><span>● zram-swap.service - Enable compressed swap in memory using zram</span></span>
<span class="line"><span>     Loaded: loaded (/usr/lib/systemd/system/zram-swap.service; disabled; vendor preset: disabled)</span></span>
<span class="line"><span>     Active: inactive (dead)</span></span></code></pre></div><p>接下來，安裝 <code>zram-generator-defaults</code> 和 <code>zram-generator</code> 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install zram-generator-defaults zram-generator</span></span></code></pre></div><p>啓用並啓動 <code>zram-swap</code> 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable zram-swap.service# systemctl start zram-swap.service</span></span></code></pre></div><p>然後驗證 <code>zram0</code> 是否存在並被用作交換空間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsblk</span></span>
<span class="line"><span>NAME          MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>sda             8:00  120G  0 disk</span></span>
<span class="line"><span>├─sda1          8:10    2G  0 part /boot</span></span>
<span class="line"><span>└─sda2          8:20  118G  0 part</span></span>
<span class="line"><span>  ├─vg01-root 253:00   10G  0 lvm  /</span></span>
<span class="line"><span>  ├─vg01-swap 253:10    3G  0 lvm  [SWAP]</span></span>
<span class="line"><span>  ├─vg01-usr  253:20   35G  0 lvm  /usr</span></span>
<span class="line"><span>  ├─vg01-tmp  253:30   15G  0 lvm  /tmp</span></span>
<span class="line"><span>  ├─vg01-var  253:40   35G  0 lvm  /var</span></span>
<span class="line"><span>  └─vg01-home 253:50   20G  0 lvm  /home</span></span>
<span class="line"><span>sr0            11:01 1024M  0 rom</span></span>
<span class="line"><span>zram0         252:00  7.5G  0 disk [SWAP]</span></span></code></pre></div><h3 id="用-zram-改進交換空間" tabindex="-1">用 zram 改進交換空間 <a class="header-anchor" href="#用-zram-改進交換空間" aria-label="Permalink to “用 zram 改進交換空間”">​</a></h3><p>這就是全部內容了。在 Fedora 上這很容易。不同的發行版可能也一樣簡單，只是軟件包名稱和命令的細節可能不同。在你的電腦上試試 zram 交換空間吧。在我的下一篇文章中，我將進一步演示一些 zram 選項。</p><hr>`,38)),n("p",null,[a[8]||(a[8]=s("via: ",-1)),p(e,{href:"https://opensource.com/article/22/11/zram-swap-linux"},{default:i(()=>[...a[7]||(a[7]=[s("https://opensource.com/article/22/11/zram-swap-linux",-1)])]),_:1})]),n("p",null,[a[13]||(a[13]=s("作者：",-1)),p(e,{href:"https://opensource.com/users/dboth"},{default:i(()=>[...a[9]||(a[9]=[s("David Both",-1)])]),_:1}),a[14]||(a[14]=s(" 選題：",-1)),p(e,{href:"https://github.com/lkxed"},{default:i(()=>[...a[10]||(a[10]=[s("lkxed",-1)])]),_:1}),a[15]||(a[15]=s(" 譯者：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1}),a[16]||(a[16]=s(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[12]||(a[12]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[19]||(a[19]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[17]||(a[17]=[s("LCTT",-1)])]),_:1}),a[20]||(a[20]=s(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...a[18]||(a[18]=[s("Linux中國",-1)])]),_:1}),a[21]||(a[21]=s(" 榮譽推出",-1))])])}const x=r(m,[["render",c]]);export{v as __pageData,x as default};
